import React, { useEffect, useState } from 'react';
import {
  Box,
  Card,
  CardMedia,
  CardContent,
  Typography,
  Button,
  Stack,
  useTheme
} from '@mui/material';
import callApi from '../../Services/callApi';
import { IProduct } from '../../Interface/IProduct';

type Product = {
  id: string;
  name: string;
  image: string;
  price: number;
  description?: string;
};

type Props = {

};


const ProductCatalog: React.FC<Props> = () => {
  const [products, setProducts] = useState<IProduct[]>([]);
  const theme = useTheme();

  useEffect(() => {
    onLoad();
  }, [

  ])

  const onLoad = async () => {
    const rs = await callApi.get('/Product/list');
    if (rs.data?.data) {
      setProducts(rs.data?.data);
    }
  }
  return (
    <Box
      display="flex"
      flexWrap="wrap"
      justifyContent="center"
      gap={2}
      p={2}
    >
      {products.map((product:IProduct) => (
        <Box
          key={product.id}
          sx={{
            width: 'calc(33.333% - 16px)', // 3 columns with gap
            maxWidth: 200,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
          }}
        >
          <Box
            component="img"
            src={product.imageUrl}
            alt={product.name}
            sx={{
              width: '100%',
              height: 120,
              objectFit: 'fill',
              borderRadius: 2,
              boxShadow: 1,
            }}
          />
          <Typography
            variant="body2"
            mt={1}
            sx={{
              width: '100%',
              textAlign: 'center',
              whiteSpace: 'nowrap',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              fontWeight: 300,
            }}
          >
            {product.name}
          </Typography>
        </Box>
      ))}
    </Box>
  );
};

export default ProductCatalog;
